preConditionHook:
// DOUBLE EMA TOUCH RUN (Brian's notes ON-38-a, #38): each of the last
// runBars bars contains both EMAs in its range. Direction-agnostic.
// EL counts with CountIF; four comparisons, no MaxList/MinList.
// MultiWalk's WFSafe_Xaverage, ported unchanged from EmaGapBar (the EMA
// reference, with the measurements): price seed on the first calculated bar
// (ctx.CurrentBar() == 1), recurrence x + sf*(p - x) in ONE statement,
// sf = 2/(Length+1) from the raw input every bar, state carried on a length
// change (EL_XAverage_Lag_Probe.txt, 2026-09-17).
emaFastSf = 2.0 / (fastLength + 1.0);
emaSlowSf = 2.0 / (slowLength + 1.0);
if (ctx.CurrentBar() == 1) {
    emaFast = close[0];
    emaSlow = close[0];
} else {
    emaFast = emaFast + emaFastSf * (close[0] - emaFast);
    emaSlow = emaSlow + emaSlowSf * (close[0] - emaSlow);
}
// LAGGED EMA READS (MEASURED, XAVERAGE_LAG_FINDINGS.md): ema[k] is bit for
// bit the value k bars earlier and reads 0.0 before that history exists, so
// the zero-initialized ring buffer below is exact and the rule guards its
// first k bars on the bar counter instead of comparing against the zero.
// Re-seeded if the depth changes.
histDepth = (int)runBars;
if (histDepth < 1) {
    histDepth = 1;
}
if (fastHistory.size() != (std::size_t)histDepth) {
    fastHistory.assign((std::size_t)histDepth, 0.0);
    slowHistory.assign((std::size_t)histDepth, 0.0);
    histCursor = 0;
}
fastHistory[histCursor] = emaFast;
slowHistory[histCursor] = emaSlow;
touchCount = 0;
for (int i = 0; i < (int)runBars; ++i) {
    double fLag = fastHistory[(histCursor + fastHistory.size() - (std::size_t)(i)) % fastHistory.size()];
    double sLag = slowHistory[(histCursor + slowHistory.size() - (std::size_t)(i)) % slowHistory.size()];
    if (el_le(low[i], fLag) && el_le(low[i], sLag) && el_ge(high[i], fLag) && el_ge(high[i], sLag)) {
        touchCount = touchCount + 1;
    }
}
histCursor = (histCursor + 1) % fastHistory.size();
runReady = ctx.CurrentBar() > (int)runBars - 1;
